package com.thakur.employee.security; import com.thakur.employee.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.security.core.userdetails.*;import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService {private final UserRepository repo;public UserDetails loadUserByUsername(String email){var u=repo.findByEmail(email).orElseThrow(()->new UsernameNotFoundException(email));return User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().name()).build();}}
